mapper.select:
SELECT id, name terminal_name
FROM bp_menu
WHERE is_deleted = 0
  and is_menu = #{isMenu}
  and parent_id = #{parentId}
ORDER BY sort

SELECT id, name, parent_id, is_menu, sort FROM bp_menu WHERE is_deleted = 0
and code like concat(#{rootMenuCode},'%') and code <> #{rootMenuCode}
ORDER BY sort

SELECT distinct t3.id, t3.name, t3.sort, t3.parent_id, t3.outside_url, t3.is_outside, t3.is_menu, t3.alias, t3.icon FROM bp_user_role t1 JOIN bp_role_menu t2 ON t1.role_id = t2.role_id JOIN bp_menu t3 ON t2.menu_id = t3.id WHERE t1.is_deleted = 0 AND t3.is_deleted = 0
AND t1.user_id = #{userId}
and t3.is_menu = 1
and t3.code like concat(#{dto.rootMenuCode},'%')
and t3.terminal_type = #{dto.terminalType}
